mapper.select:
select deviceSatelliteName, channelName, raw, checkResultName
from ${devicePath}
order by time desc limit ${limit} offset ${offset} align by device

select count(raw) as total
from ${devicePath}
align by device

select tmName, value, stateName, processedAt from ${devicePath}
value is not null
order by time desc limit 1 align by device

select value from ${devicePath}
value is not null
order by time desc limit 120 align by device

select deviceSatelliteName, channelName, checkResultName, raw from ${devicePath}
checkResultName != '正常'
order by time desc limit ${limit} offset ${offset} align by device

select count(raw) as total from ${devicePath}
checkResultName != '正常'
align by device
